(91012096,94193538,2,0,'How many more supplies are needed to send ground assaults?',9128,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91012096,94193539,3,0,'Charge!!! Run ''em through!',9050,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91012097,94193554,2,0,'How many more supplies are needed to send ground assaults?',9128,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91012097,94193555,3,0,'Charge!!! Run ''em through!',9050,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013176,94210817,1,0,'How many more supplies are needed for the next upgrade?',9130,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013176,94210818,2,0,'Upgrade to seasoned units!',8718,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013176,94210819,3,0,'Upgrade to veteran units!',8719,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013176,94210820,4,0,'Upgrade to champion units!',8723,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013257,94212113,1,0,'How many more supplies are needed for the next upgrade?',9130,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013257,94212114,2,0,'Upgrade to seasoned units!',8718,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013257,94212115,3,0,'Upgrade to veteran units!',8719,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013257,94212116,4,0,'Upgrade to champion units!',8723,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013179,94210865,1,0,'I''ll get that beacon to the crater safely, Guse. You can count on me!',8667,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013179,94210866,2,0,'The time has come, Guse. You fly again!',10341,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013180,94210881,1,0,'Consider it done, Jeztor. Give me a beacon.',8669,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013180,94210882,2,0,'Jeztor lives! Time to light up the Valley sky, Commander.',10343,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013181,94210897,1,0,'I''m ready to plant the beacon, Mulv. Give me a beacon.',8671,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013181,94210898,2,0,'Do you feel it, Mulv? The need? You have to want it before I can give you the command. Who am I kidding. Get out there!',10346,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013438,94215009,1,0,'Give me the beacon, Slidore! Also, you still stink!',8796,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013438,94215010,2,0,'I want a surgical strike, Slidore. Carpet the road with fire!',10351,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013439,94215025,1,0,'I am ready to rock, Vipore! Give me a beacon.',8799,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013439,94215026,2,0,'Tactical suppression fire, Vipore. Lay it on thick.',10353,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013437,94214993,1,0,'I''m your man, Ich. Give me a beacon!',8793,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013437,94214994,2,0,'Take the base. We''ll be sieging it from the ground.',10349,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013441,94215057,1,0,'YAW! Er, to the front lines with you!',8903,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013577,94217233,1,0,'YAW! Er, to the front lines with you!',8903,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013236,94211777,1,0,'How much more blood is needed, Commander?',8641,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013236,94211778,2,0,'We must be close, Commander. I can feel the elements stirring.',8643,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013236,94211779,3,0,'I sense a great power among us, Commander. Is the spell ready?',8645,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013442,94215073,1,0,'Have you made contact with Ivus, Archdruid?',8757,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013442,94215074,2,0,'The air is abuzz with energy, Archdruid. What is the status of the Forest Lord?',8759,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0),
(91013442,94215075,3,0,'The forest shakes and shudders! The winds howl! Does the Forest Lord approach?',8761,0,0,0,0,NULL,0,0,'',0,NULL,NULL,0);
