-- Alterac Valley (classic): the assaults of the VMaNGOS battleground script
-- The quest givers and their escorts get the C++ scripts in alterac_valley.cpp; their SmartAI rows only did combat spells,
-- which the scripts now cast. The escort routes are the VMaNGOS script_waypoint points (waypoint_path 811000000 + entry * 10).

-- escort routes
DELETE FROM `waypoint_path_node` WHERE `PathId` IN (811131790,811131800,811131810,811134370,811134380,811134390,811134400,811134410,811135760,811135770,811134460,811134490,811135240,811135280,811132360,811134420,811132560,811134190);
DELETE FROM `waypoint_path` WHERE `PathId` IN (811131790,811131800,811131810,811134370,811134380,811134390,811134400,811134410,811135760,811135770,811134460,811134490,811135240,811135280,811132360,811134420,811132560,811134190);

